using System;using System.IO;using System.Drawing;using System.Windows.Forms;
namespace EanEtikety {
public partial class MainForm {
 void AddImage(){using(var file=new OpenFileDialog{Filter="PNG / JPEG / SVG|*.png;*.jpg;*.jpeg;*.svg"})if(file.ShowDialog(this)==DialogResult.OK){try{var image=Assets.Import(file.FileName);int index=-3-symbols.Count;ChangeDocument(s=>{if(s.Symbols.Count>=20)throw new Exception(Loc.T("Najviac 20 symbolov."));double width=Math.Min(30,s.Width-6);double height=width*image.PixelHeight/Math.Max(1d,image.PixelWidth);if(height>s.Height-6){width*=Math.Max(1,s.Height-6)/height;height=Math.Max(1,s.Height-6);}if(width<1||height<1)throw new InvalidOperationException(Loc.T("Obrázok má príliš extrémny pomer strán."));s.Symbols.Add(new SymbolItem{Image=image,Width=width,Height=height});});preview.SelectElement(index);}catch(Exception ex){Error(ex);}}}
 void AddMatrix(){EditAsset(-2,true);}
 void EditAsset(int index,bool matrix){bool existing=index<=-3&&-3-index<symbols.Count;var symbol=existing?symbols[-3-index].Copy():new SymbolItem{Width=24,Height=24,Matrix=new MatrixContent()};using(var f=FeatureForm(matrix?"QR / Data Matrix":"Obrázok",480,590)){var p=FeatureStack(f);TextBox text=null;ComboBox type=null;NumericUpDown x=null,y=null,w=null,h=null;
  if(matrix){type=Choice(p,"Typ kódu",new[]{"QR","Data Matrix"},symbol.Matrix.Type=="QR"?0:1);text=Input(p,"Obsah kódu",symbol.Matrix.Data);text.Multiline=true;text.Height=120;StackAdd(p,new Label{Text=Loc.T("Bežný Data Matrix, nie GS1 DataMatrix. Premenné zapisujte ako {serial}."),AutoSize=true,MaximumSize=new Size(400,0)});}
  else{x=Number(p,"Výrez X (%)",(decimal)symbol.Image.CropX*100,0,99,2);y=Number(p,"Výrez Y (%)",(decimal)symbol.Image.CropY*100,0,99,2);w=Number(p,"Šírka výrezu (%)",(decimal)symbol.Image.CropWidth*100,1,100,2);h=Number(p,"Výška výrezu (%)",(decimal)symbol.Image.CropHeight*100,1,100,2);}
  var keep=Check(p,"Zachovať pomer strán",symbol.Image==null||symbol.Image.KeepAspect);keep.Enabled=!matrix;AddAccept(f,p,delegate{if(matrix){symbol.Matrix.Type=type.SelectedIndex==0?"QR":"Data Matrix";symbol.Matrix.Data=text.Text;if(!text.Text.Contains("{"))Assets.Matrix(symbol.Matrix);symbol.Height=symbol.Width;}else{symbol.Image.KeepAspect=keep.Checked;symbol.Image.CropX=(double)x.Value/100;symbol.Image.CropY=(double)y.Value/100;symbol.Image.CropWidth=(double)w.Value/100;symbol.Image.CropHeight=(double)h.Value/100;Assets.Validate(symbol.Image);if(keep.Checked)symbol.Height=symbol.Width*symbol.Image.PixelHeight*symbol.Image.CropHeight/(symbol.Image.PixelWidth*symbol.Image.CropWidth);}
   ChangeDocument(s=>{if(existing)s.Symbols[-3-index]=symbol;else{if(s.Symbols.Count>=20)throw new Exception(Loc.T("Najviac 20 symbolov."));s.Symbols.Add(symbol);}});preview.SelectElement(existing?index:-3-symbols.Count+1);
  });f.ShowDialog(this);}}
}
}
